async function e(r){const t=await chrome.tabs.sendMessage(r,{type:"ping"},{frameId:0});if(!(t!=null&&t.ready)||!t.url)throw Error("网页标注界面尚未就绪");return t}async function a(r){try{return await e(r)}catch{await chrome.scripting.insertCSS({target:{tabId:r},files:["highlights.css"]}),await chrome.scripting.executeScript({target:{tabId:r},files:["content.js"]});for(let t=0;t<20;t++)try{return await e(r)}catch{await new Promise(i=>setTimeout(i,50))}throw Error("网页标注界面连接失败，请刷新网页，并检查插件的网站访问权限。")}}export{a as ensurePageBridge};
